23	final class QuotedScanner
24	{
25	    /**
26	     * What each backslash escape in a string stands for.
27	     */
28	    private const ESCAPES = [
29	        'n' => "\n",
30	        't' => "\t",
31	        'r' => "\r",
32	        'b' => "\x08",
33	        'f' => "\f",
34	        '0' => "\0",
35	        '\\' => '\\',
36	        "'" => "'",
37	        '"' => '"',
38	        '`' => '`',
39	    ];
40	
41	    /**
42	     * Reads a character string written in single or double quotes.
43	     *
44	     * @param SourceCursor $cursor The place in the query the string starts at
45	     *
46	     * @example A string is read as the characters between its quotes
47	     *     \App\Gql\Lexing\QuotedScanner::text(new \App\Gql\Lexing\SourceCursor("'/users'"))->value // => '/users'
48	     * @example An escape stands for the character it names
49	     *     \App\Gql\Lexing\QuotedScanner::text(new \App\Gql\Lexing\SourceCursor('"a\\tb"'))->value // => "a\tb"
50	     * @example A doubled quote stands for one of itself
51	     *     \App\Gql\Lexing\QuotedScanner::text(new \App\Gql\Lexing\SourceCursor("'it''s'"))->value // => "it's"
52	     *
53	     * @return Token The string, with what it was written as and what it stands for
54	     *
55	     * @throws GqlException If the string is never closed
56	     */
57	    public static function text(SourceCursor $cursor): Token
58	    {
59	        $line = $cursor->line();
60	        $column = $cursor->column();
61	        $offset = $cursor->offset();
62	        $quote = $cursor->take(1);
63	        $lexeme = $quote;
64	        $value = '';
65	
66	        while (!$cursor->atEnd()) {
67	            $next = $cursor->peek();
68	            if ($next === $quote && $cursor->peek(1) === $quote) {
69	                $lexeme .= $cursor->take(2);
70	                $value .= $quote;
71	
72	                continue;
73	            }
74	            if ($next === $quote) {
75	                return new Token(TokenKind::Text, $lexeme.$cursor->take(1), $value, $line, $column, $offset);
76	            }
77	            if ($next === '\\') {
78	                $lexeme .= $cursor->take(1);
79	                $escape = $cursor->peek();
80	                $lexeme .= $cursor->take(1);
81	                $value .= self::ESCAPES[$escape] ?? $escape;
82	
83	                continue;
84	            }
85	            $lexeme .= $cursor->take(1);
86	            $value .= $next;
87	        }
