96	     * carries a character a bare name may not. A doubled backtick stands for one of
97	     * itself, which is the only escape a name has.
98	     *
99	     * @param SourceCursor $cursor The place in the query the name starts at
100	     *
101	     * @example A quoted name is the text between its backticks
102	     *     \App\Gql\Lexing\QuotedScanner::name(new \App\Gql\Lexing\SourceCursor('`return`'))->value // => 'return'
103	     * @example A doubled backtick stands for one of itself
104	     *     \App\Gql\Lexing\QuotedScanner::name(new \App\Gql\Lexing\SourceCursor('`a``b`'))->value // => 'a`b'
105	     *
106	     * @return Token The name, with what it was written as and what it stands for
107	     *
108	     * @throws GqlException If the name is never closed
109	     */
110	    public static function name(SourceCursor $cursor): Token
111	    {
112	        $line = $cursor->line();
113	        $column = $cursor->column();
114	        $offset = $cursor->offset();
115	        $lexeme = $cursor->take(1);
116	        $value = '';
117	
118	        while (!$cursor->atEnd()) {
119	            if ($cursor->peek() === '`' && $cursor->peek(1) === '`') {
120	                $lexeme .= $cursor->take(2);
121	                $value .= '`';
122	
123	                continue;
124	            }
125	            if ($cursor->peek() === '`') {
126	                return new Token(TokenKind::QuotedName, $lexeme.$cursor->take(1), $value, $line, $column, $offset);
127	            }
128	            $value .= $cursor->peek();
129	            $lexeme .= $cursor->take(1);
130	        }
131	
132	        throw GqlException::syntax('a quoted name is never closed', $line, $column, '"'.$lexeme.'"');
133	    }
134	}

