10	use App\Gql\Evaluation\AggregateDetection;
11	use App\Gql\Evaluation\ExpressionEvaluation;
12	use App\Gql\GqlException;
13	use App\Gql\Syntax\Clause\Projection;
14	use App\Gql\Syntax\Clause\ReturnClause;
15	use App\Gql\Syntax\Expression;
16	
17	/**
18	 * Running a RETURN: deciding what the reader is shown.
19	 *
20	 * The one real decision here is whether the projection summarises its rows or reports
21	 * them, and it is made from the shape of the expressions rather than from the data:
22	 * a projection holding a summary anywhere inside it produces one row per group, and
23	 * one holding none produces one row per row. Grouping without a `GROUP BY` makes a
24	 * single group of everything, which is why `RETURN count(*)` answers once.
25	 *
26	 * Projected columns are added to the row they came from rather than replacing it.
27	 * That is what lets an ordering written after the projection sort by something the
28	 * projection did not show — `RETURN a, b ORDER BY r.creationDate` — which GQL allows
29	 * and a reader reaches for more often than it sounds.
30	 *
31	 * @visibility App\Gql
32	 */
33	final class ReturnExecution
34	{
35	    /**
36	     * @param RowExecution $rows How rows are ordered and paged
37	     */
38	    public function __construct(
39	        private readonly RowExecution $rows,
40	    ) {}
41	
42	    /**
43	     * Returns what the columns of the result are called.
44	     *
45	     * A projection that asks for everything is headed by the names that are in scope
46	     * where it is written, which is decided when the query runs rather than when it
47	     * is read.
48	     *
49	     * @param ReturnClause $clause The clause
50	     * @param BindingTable $table  The rows it is given
51	     *
52	     * @example A projection that asks for everything shows what is bound
53	     *     $row = \App\Gql\Binding\BindingRow::unit()->with('p', new \App\Gql\Datum\NullDatum());
54	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
55	     *     $execution->headings(new \App\Gql\Syntax\Clause\ReturnClause(), new \App\Gql\Binding\BindingTable([$row])) // => ['p']
56	     *
57	     * @return list<string> The headings, in the order they are shown
58	     */
59	    public function headings(ReturnClause $clause, BindingTable $table): array
60	    {
61	        if ($clause->everything()) {
62	            return $table->names();
63	        }
64	
65	        return array_map(static fn (Projection $column): string => $column->heading(), $clause->columns);
66	    }
67	
68	    /**
69	     * Returns the rows a RETURN produces.
70	     *
71	     * @param ReturnClause $clause The clause
72	     * @param BindingTable $table  The rows it is given
73	     *
74	     * @example A projection that summarises answers once, even over no rows at all
75	     *     $counted = new \App\Gql\Syntax\Expression\CallExpression('count', [], false, true);
76	     *     $clause = new \App\Gql\Syntax\Clause\ReturnClause([new \App\Gql\Syntax\Clause\Projection($counted, 'n', 'count(*)')]);
77	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
78	     *     $execution->run($clause, \App\Gql\Binding\BindingTable::nothing())->rows[0]->value('n')->toText() // => '0'
79	     *
80	     * @return BindingTable The rows it produces
81	     *
82	     * @throws GqlException If a column cannot be worked out
83	     */
84	    public function run(ReturnClause $clause, BindingTable $table): BindingTable
85	    {
86	        $produced = $this->summarises($clause)
87	            ? $this->summarised($clause, $table)
88	            : $this->reported($clause, $table);
89	
90	        if ($clause->distinct) {
91	            $produced = self::once($this->headings($clause, $table), $produced);
92	        }
93	        if ($clause->orderBy !== []) {
94	            $produced = $this->rows->sorted($clause->orderBy, $produced);
95	        }
96	        if ($clause->page !== null) {
97	            $produced = array_values(array_slice($produced, $clause->page->offset, $clause->page->limit));
98	        }
99	
100	        return new BindingTable($produced);
101	    }
102	
103	    /**
104	     * Reports whether a projection summarises its rows rather than reporting them.
105	     *
106	     * @param ReturnClause $clause The clause
107	     *
108	     * @example A projection that groups summarises
109	     *     $key = new \App\Gql\Syntax\Expression\VariableExpression('kind');
110	     *     $clause = new \App\Gql\Syntax\Clause\ReturnClause([], false, [$key]);
111	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
112	     *     $execution->summarises($clause) // => true
113	     * @example A projection that shows properties does not
114	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
115	     *     $execution->summarises(new \App\Gql\Syntax\Clause\ReturnClause()) // => false
116	     *
117	     * @return bool True when it produces one row per group
118	     */
119	    public function summarises(ReturnClause $clause): bool
120	    {
121	        if ($clause->groupBy !== []) {
122	            return true;
123	        }
124	        foreach ($clause->columns as $column) {
125	            if (AggregateDetection::within($column->value)) {
126	                return true;
127	            }
128	        }
129	
130	        return false;
131	    }
132	
133	    /**
134	     * Returns one row per row, with the projected columns added to it.
135	     *
136	     * @param ReturnClause $clause The clause
137	     * @param BindingTable $table  The rows it is given
138	     *
139	     * @example A projection that asks for everything leaves its rows alone
140	     *     $row = \App\Gql\Binding\BindingRow::unit()->with('p', new \App\Gql\Datum\IntegerDatum(1));
141	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
142	     *     $execution->reported(new \App\Gql\Syntax\Clause\ReturnClause(), new \App\Gql\Binding\BindingTable([$row]))[0]->value('p')->toText() // => '1'
143	     *
144	     * @return list<BindingRow> The rows
145	     *
146	     * @throws GqlException If a column cannot be worked out
147	     */
148	    public function reported(ReturnClause $clause, BindingTable $table): array
149	    {
150	        $evaluation = new ExpressionEvaluation();
151	        $produced = [];
152	        foreach ($table->rows as $row) {
153	            $values = [];
154	            foreach ($clause->columns as $column) {
155	                $values[$column->heading()] = $evaluation->evaluate($column->value, $row);
156	            }
157	            $produced[] = $row->withAll($values);
158	        }
159	
160	        return $produced;
161	    }
162	
163	    /**
164	     * Returns one row per group, with the summaries worked out over each group.
165	     *
166	     * @param ReturnClause $clause The clause
167	     * @param BindingTable $table  The rows it is given
168	     *
169	     * @example Summarising no rows at all still answers once
170	     *     $counted = new \App\Gql\Syntax\Expression\CallExpression('count', [], false, true);
171	     *     $clause = new \App\Gql\Syntax\Clause\ReturnClause([new \App\Gql\Syntax\Clause\Projection($counted, 'n', 'count(*)')]);
172	     *     $execution = new \App\Gql\Execution\ReturnExecution(new \App\Gql\Execution\RowExecution(new \App\Gql\Evaluation\ExpressionEvaluation()));
173	     *     count($execution->summarised($clause, \App\Gql\Binding\BindingTable::nothing())) // => 1
174	     *
175	     * @return list<BindingRow> The rows
176	     *
177	     * @throws GqlException If a column cannot be worked out
178	     */

